#!/usr/bin/env python3
"""Patch 109: reports follow the real pipeline. Delivered means approved AND accepted by Xtrium; an approved source not yet sent is its own stage; an escalation Xtrium has not accepted stays blocked; peer reviewers who flagged fields are shown even if they did not press Submit. Needs patch 96 (reports and briefs). Run from the repo root. Safe to run twice."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {}
MOD = {'backend/app/services/batch_report.py': [('    ClientQuestion, ExtractedRecord, ExtractionJob, ReviewStatus, Source, SourceLinkCheck, SourceStatus, User,\n', '    ClientQuestion, ExtractedRecord, ExtractionJob, QualityFinding, ReviewStatus, Source, SourceLinkCheck, SourceStatus, User,\n'), ('    ("delivered", "Delivered"), ("signoff", "Ready for sign-off"),', '    ("delivered", "Delivered"), ("ready_to_send", "Approved, not yet sent to Xtrium"), ("signoff", "Ready for sign-off"),'), ('    if st == SourceStatus.APPROVED:\n        return "delivered"\n', '    if st == SourceStatus.APPROVED:\n        # Delivered means Xtrium has it. A source pulled from Xtrium that is approved but not yet accepted back is waiting to be sent.\n        pulled = bool(getattr(s, "external_ref_id", None) or getattr(s, "external_system", None))\n        return "delivered" if (s.xtrium_submitted_at or not pulled) else "ready_to_send"\n'), ('                        .filter(ExtractionJob.source_id.in_(ids), ExtractedRecord.is_escalation_only == True,  # noqa: E712\n                                ExtractedRecord.review_status != ReviewStatus.APPROVED).all()):\n        src = next(x for x in mine if x.id == sid)\n        if src.status != SourceStatus.APPROVED:\n            blocked[sid] = {"kind": "nodata", "reason": (reason or "No extractable data").strip(), "detail": None}\n', '                        .filter(ExtractionJob.source_id.in_(ids), ExtractedRecord.is_escalation_only == True).all()):  # noqa: E712\n        src = next(x for x in mine if x.id == sid)\n        # an escalation counts as open until Xtrium has accepted it back, even when it was approved here\n        if src.status != SourceStatus.APPROVED:\n            blocked[sid] = {"kind": "nodata", "reason": (reason or "No extractable data").strip(), "detail": None}\n        elif not src.xtrium_submitted_at:\n            blocked[sid] = {"kind": "nodata", "reason": (reason or "No extractable data").strip(), "detail": "Escalated here, but Xtrium has not accepted it back yet"}\n'), ('    qrow = {r["source_id"]: r for r in (sc or {}).get("batches", [])}\n\n    rows, stages =', '    qrow = {r["source_id"]: r for r in (sc or {}).get("batches", [])}\n    # peer reviewers who raised at least one finding on a source, whether or not they pressed Submit\n    flagged: dict = {}\n    for sid_, uid_ in db.query(QualityFinding.source_id, QualityFinding.raised_by).filter(QualityFinding.source_id.in_(ids), QualityFinding.origin == "reviewer").distinct().all():\n        flagged.setdefault(sid_, set()).add(uid_)\n\n    rows, stages ='), ('"records": n, "approved": ok, "peers_done": sum(1 for p in s.peer_reviews if p.status == "submitted"), "peers_total": len(s.peer_reviews),', '"records": n, "approved": ok, "peers_done": sum(1 for p in s.peer_reviews if p.status == "submitted"), "peers_total": len(s.peer_reviews),\n            "peers_flagged": len(flagged.get(s.id, set()) & {p.user_id for p in s.peer_reviews}), "pulled_at": s.created_at.isoformat() if s.created_at else None,'), ('    inflight = total - delivered - stages["blocked"]\n    if inflight:', '    ready = stages["ready_to_send"]\n    inflight = total - delivered - stages["blocked"] - ready\n    if ready:\n        lines.append(f"{ready} approved {\'source is\' if ready == 1 else \'sources are\'} waiting to be sent back to Xtrium.")\n    if inflight:'), ('    if delivered and any(r["submitted_to_xtrium"] for r in rows):\n        n_sub = sum(1 for r in rows if r["submitted_to_xtrium"])\n        cards.append({"title": f"{n_sub} sent to Xtrium", "text": f"{n_sub} of {delivered} delivered sources have been submitted back to Xtrium."})', '    if (delivered or ready) and any(r["submitted_to_xtrium"] for r in rows):\n        n_sub = sum(1 for r in rows if r["submitted_to_xtrium"])\n        cards.append({"title": f"{n_sub} sent to Xtrium", "text": f"{n_sub} of {delivered + ready} approved sources have been submitted back to Xtrium."})'), ('"blocked": stages["blocked"], "on_hold": sum(1 for r in rows if r.get("on_hold")), "in_progress": inflight,', '"blocked": stages["blocked"], "ready_to_send": ready, "on_hold": sum(1 for r in rows if r.get("on_hold")), "in_progress": inflight,'), ('    if totals["submitted"] < tot_deliv:\n        nxt.append({"title": "Send delivered work to Xtrium", "text": f"{tot_deliv - totals[\'submitted\']} approved sources have not been submitted back to Xtrium yet."})', '    if stage_tot.get("ready_to_send"):\n        nxt.append({"title": "Send approved work to Xtrium", "text": f"{stage_tot[\'ready_to_send\']} approved sources have not been submitted back to Xtrium yet."})')], 'frontend/src/components/enh/BatchReport.tsx': [("not_started: '#d1d5db', blocked: '#f97316',", "not_started: '#d1d5db', blocked: '#f97316', ready_to_send: '#60a5fa',"), ('<td className="px-2.5 tabular-nums">{s.peers_done}/{s.peers_total}</td>', '<td className="px-2.5 tabular-nums whitespace-nowrap">{s.peers_done}/{s.peers_total}{s.peers_flagged > 0 && s.peers_done < s.peers_total ? <span style={{ color: \'#6b7280\' }}> · {s.peers_flagged} flagged</span> : null}</td>')], 'frontend/src/components/enh/reports/EngagementDeck.tsx': [("not_started: '#d4dbe8', blocked: RED }", "not_started: '#d4dbe8', blocked: RED, ready_to_send: '#4f86e8' }"), ("<td style={{ padding: '11px 12px' }}>{s.peers_done} of {s.peers_total}</td>", "<td style={{ padding: '11px 12px' }}>{s.peers_done} of {s.peers_total}{s.peers_flagged > 0 && s.peers_done < s.peers_total ? `, ${s.peers_flagged} flagged` : ''}</td>")]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
